#include <iostream>
#include <iterator>
#include <vector>
template <class Iterator1, class Iterator2>
bool operator>=(const std::reverse_iterator<Iterator1>& x, const std::reverse_iterator<Iterator2>& y) {
  return x.base() <= y.base();
}
int main() {
  std::vector<int> vec = {1, 2, 3, 4, 5};
  auto rbegin = std::rbegin(vec);
  auto rend = std::rend(vec);
  auto rit = rbegin + 2;
  if (rit >= rbegin) {
    std::cout << "rit is greater than or equal to rbegin" << std::endl;
  }
  return 0;
}
